package com.antirea.runtime

import java.io.File
import java.security.MessageDigest
import java.security.SecureRandom
import java.util.Base64

/**
 * Anti-REA v1.0 Batch A JVM test — L13 asset decrypt + L49 native
 * gate fallback. Pure Kotlin + JDK, no Android imports, no device.
 *
 * Usage (vectors file generated by the Batch A harness from
 * transformer/native.py — the SAME encryptor the CLI will use, so
 * this tests real cross-language interop, not a Kotlin-only echo):
 *   kotlinc -d hiding-test.jar ReaRuntime.kt ReaAssets.kt ReaNative.kt \
 *       tests/HidingTest.kt
 *   java -cp hiding-test.jar com.antirea.runtime.HidingTestKt \
 *       tests/hiding_vectors.txt
 *
 * Vectors file lines (base64 unless noted):
 *   1. plaintext asset bytes
 *   2. cipher bytes (raw, from encrypt_asset_bytes)
 *   3. key part 1 (base64)
 *   4. key part 2 (base64)
 *   5. tampered cipher bytes (one byte flipped)
 *
 * Expected output ends with TEST-PASS. Any failure throws and the
 * JVM exits non-zero — there is no silent PASS.
 */
fun main(args: Array<String>) {
    require(args.isNotEmpty()) { "usage: HidingTestKt <vectors-file>" }
    val lines = File(args[0]).readLines()
    require(lines.size >= 5) { "vectors file needs 5 lines, got ${lines.size}" }
    val b64 = Base64.getDecoder()

    // --- L13: Python-encrypted vector round-trip -------------------
    val plain = b64.decode(lines[0])
    val cipher = b64.decode(lines[1])
    val part1 = lines[2]
    val part2 = lines[3]
    val tampered = b64.decode(lines[4])
    require(cipher.size == plain.size + 32) {
        "L13: cipher must be plain+32, got ${cipher.size} vs ${plain.size}"
    }
    val out = ReaAssets.decryptAsset(cipher, part1, part2)
    require(out.contentEquals(plain)) { "L13: round-trip mismatch" }
    println("ASSET-OK: ${plain.size} bytes round-tripped "
        + "(cipher ${cipher.size} bytes)")

    // Tampered cipher must refuse, never return wrong bytes.
    try {
        ReaAssets.decryptAsset(tampered, part1, part2)
        error("L13: tampered cipher was NOT refused")
    } catch (e: IllegalStateException) {
        println("ASSET-TAMPER-REFUSED: ${e.message}")
    }

    // Wrong key part must refuse too.
    val wrongPart2 = Base64.getEncoder().encodeToString(
        b64.decode(part2).also { it[0] = (it[0].toInt() xor 0x01).toByte() }
    )
    try {
        ReaAssets.decryptAsset(cipher, part1, wrongPart2)
        error("L13: wrong key part was NOT refused")
    } catch (e: IllegalStateException) {
        println("ASSET-WRONGKEY-REFUSED: ${e.message}")
    }

    // Text + base64 wrappers.
    val textPlain = "asset-text-vector-hello".toByteArray(Charsets.UTF_8)
    val textCipher: Triple<ByteArray, String, String> = run {
        val rnd = SecureRandom()
        val key = ByteArray(32).also { rnd.nextBytes(it) }
        val p1 = ByteArray(32).also { rnd.nextBytes(it) }
        val p2 = ByteArray(32) { i -> (key[i].toInt() xor p1[i].toInt()).toByte() }
        val raw = MessageDigest.getInstance("SHA-256").digest(textPlain) + textPlain
        val c = ByteArray(raw.size) { i ->
            (raw[i].toInt() xor key[i % key.size].toInt()).toByte()
        }
        Triple(c, Base64.getEncoder().encodeToString(p1),
            Base64.getEncoder().encodeToString(p2))
    }
    val textOut = ReaAssets.decryptAssetText(
        textCipher.first, textCipher.second, textCipher.third
    )
    require(textOut == "asset-text-vector-hello") {
        "L13: text round-trip mismatch: $textOut"
    }
    val b64Out = ReaAssets.decryptAssetBase64(
        Base64.getEncoder().encodeToString(textCipher.first),
        textCipher.second, textCipher.third
    )
    require(b64Out.contentEquals(textPlain)) { "L13: base64 round-trip mismatch" }
    println("ASSET-TEXT-OK: decryptAssetText + decryptAssetBase64 round-trip")

    // --- L49: native gate prefers native, falls back to Java --------
    // On the plain JVM there is no arm64 libreagate.so, so nativeLoaded
    // must be false and integrityGate() must take the Java path.
    println("NATIVE-LOADED: ${ReaNative.nativeLoaded}")
    require(!ReaNative.nativeLoaded) {
        "L49: native lib unexpectedly loaded on the plain JVM"
    }
    val data = "reagate-test-bytes".toByteArray(Charsets.UTF_8)
    val hex = ReaRuntime.sha256Hex(data)
    require(
        ReaRuntime.sha256Hex("abc".toByteArray(Charsets.UTF_8))
            == "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
    ) {
        "L49: sha256 sanity vector failed"
    }
    require(ReaNative.javaGate(hex, data)) { "L49: javaGate true-case failed" }
    require(!ReaNative.javaGate("00" + hex.substring(2), data)) {
        "L49: javaGate false-case failed"
    }
    require(!ReaNative.javaGate(hex, "tampered".toByteArray())) {
        "L49: javaGate tampered-data case failed"
    }
    require(ReaNative.integrityGate(hex, data)) {
        "L49: integrityGate fallback true-case failed"
    }
    require(!ReaNative.integrityGate("00" + hex.substring(2), data)) {
        "L49: integrityGate fallback false-case failed"
    }
    println("NATIVE-FALLBACK-OK: javaGate + integrityGate agree "
        + "(true on match, false on wrong hash / tampered data)")

    println("TEST-PASS")
}
